function RestartGI_RT(scene, camera, light) {
  // Initialize variables
  gI_buffer = new empty buffer  // store final result
  reflective_L0 = new empty buffer  // store diffuse reflections
  refractive_L0 = new empty buffer  // store refractions
  sample_count = 0

  // Shade each pixel in the camera's view
  for each pixel in image {
    // Calculate the camera's view direction and radiance at this pixel
    view_dir = get_view_direction(camera, pixel)
    radiance = calculate_radiance(camera, pixel, view_dir)

    // Perform indirect diffuse lighting ( diffuse reflections )
