    refractive_L0[pixel] = refracted_radiance

    // Calculate the final color at this pixel
    gI_buffer[pixel] = combine_radiance(radiance, reflective_L0[pixel], refractive_L0[pixel])

  }

  // Perform final diffusion and radiance scaling
  final_gas = perform_final_diffusion(gI_buffer, scene, light)
  gI_buffer = scale_radiance(final_gas, scene)

  return gI_buffer
}

// Function to perform diffuse reflections
function perform_diffuse_reflections(scene, light, view_dir) {
  diffuse_reflective_L0 = new empty buffer

  for each light source in scene {
    // Calculate the light direction and intensity
    light_dir = get_light_direction(light, view_dir)
    light_intensity = calculate_light_intensity(light, view_dir)

    // Calculate the diffuse reflection (Lambertian) for each object in the scene
    for each object in scene {
      // Calculate the normal and material properties
      normal = get_object_normal(object)
      material = get_object_material(object)

      // Calculate the diffuse reflection
      diffuse_reflection = dotProduct(normal, light_dir) * light_intensity

      // Add to the cumulative diffuse reflection
      diffuse_reflective_L0 += diffuse_reflection * material.diffuse_color
    }

  }

  return diffuse_reflective_L0
}

// Function to perform refractions ( transparency )
function perform_refractions(scene, light, view_dir, radiance) {
  refracted_radiance = new empty buffer

  for each object in scene {
    // Calculate the normal and material properties
    normal = get_object_normal(object)
    material = get_object_material(object)

    // Check if the object is transparent
    if material.transparent {
      // Calculate the refraction ray
      refraction_ray = get_refraction_ray(view_dir, normal, material.refractive_index)

      // Shoot a ray through the refraction ray and calculate the radiance
      refracted_radiance += shoot_ray(refraction_ray, light, scene) * material.transparency
    }

  }

  return refracted_radiance
}
