```javascript
let angle = 0;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  background(0);
  rotateY(angle);
  rotateX(angle);

  drawHeart();

  angle += 0.01;
}

function drawHeart() {
  fill(255, 0, 0); // Red
  noStroke();

  let h = height / 2; // Heart's height
  let w = width / 2; // Heart's width

  beginShape();
  for (let i = 0; i < 360; i++) {
    let r = map(sin(radians(i)) + 1, -1, 1, 0, 1);
    let x = w * r * cos(radians(i)) + w;
    let y = h * r * sin(radians(i)) - h;
    vertex(x, y);
  }
  endShape(CLOSE);
}
```

