```
import React, { useState, useEffect } from 'react';

const AutoComplete = ({ suggestions, onSuggestionSelected }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [hoveredSuggestion, setHoveredSuggestion] = useState(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      const filteredSuggestions = suggestions.filter((s) => {
        return s.toLowerCase().includes(inputValue.toLowerCase());
      });
      setSuggestionsList(filteredSuggestions);
    }, 200);

    return () => {
      clearTimeout(timer);
    };
  }, [inputValue, suggestions]);

  const handleInputChange = (event) => {
    const currentValue = event.target.value;
    setInputValue(currentValue);
  };

  const handleSuggestionClick = (suggestion) => {
    onSuggestionSelected(suggestion);
    setInputValue('');
  };

  const handleSuggestionHover = (suggestion) => {
    setHoveredSuggestion(suggestion);
  };

  const handleSuggestionBlur = () => {
    setHoveredSuggestion(null);
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Type to search..."
      />
      {suggestionsList.length > 0 && (
        <ul>
          {suggestionsList.map((suggestion, index) => {
            let className = 'suggestion';
            if (hoveredSuggestion === suggestion) {
              className += ' hovered';
            }
            if (index === 0) {
              className += ' first';
            }
            if (index === suggestionsList.length - 1) {
              className += ' last';
            }

            return (
              <li
                key={suggestion}
                className={className}
                onMouseEnter={() => handleSuggestionHover(suggestion)}
                onMouseLeave={handleSuggestionBlur}
                onClick={() => handleSuggestionClick(suggestion)}
              >
                {suggestion}
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
};

export default AutoComplete;
```
