Voici un exemple de code C# qui utilise `HttpListener` pour créer un serveur HTTP simple qui répond avec "Hello" sur la page "hello" au port 8080 :
```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        // Crée un objet HttpListener
        HttpListener listener = new HttpListener();

        // Configure l'écoute pour le port 8080 et la page "hello"
        listener.Prefixes.Add("http://localhost:8080/hello");

        // Démarrer l'écoute
        listener.Start();

        Console.WriteLine("Server started. Press any key to exit...");

        // Ecouter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Traitement de la requête
            string response = "Hello";

            // Envoi de la réponse
            context.Response.StatusCode = 200;
            byte[] buffer = Encoding.UTF8.GetBytes(response);
            context.Response.ContentLength64 = buffer.Length;
            Stream output = context.Response.OutputStream;
            output.Write(buffer, 0, buffer.Length);
            output.Close();
        }
    }
}
```
