Here's a simple example using the X.org Xlib library:
```c
#include <X11/Xlib.h>
#include <stdio.h>
#include <stdlib.h>

int main() {
    // Open a connection to the X server
    Display *dpy = XOpenDisplay(NULL);
    if (dpy == NULL) {
        fprintf(stderr, "Cannot open display\n");
        return 1;
    }

    // Create a window to receive keyboard events
    Window win = XCreateSimpleWindow(dpy, RootWindow(dpy, 0), 0, 0, 1, 1, 0, 0, NULL);
    XSetWNose Graves(XCreateSimpleWindow);

    // Grab the keyboard
    XGrabKey(dpy, AnyKey, AnyModifier, win, TRUE, GrabModeAsync, GrabModeAsync);

    // Main loop
    while (1) {
        // Read events from the X server
        XEvent ev;
        while (XPending(dpy) > 0) {
            XNextEvent(dpy, &ev);
            // Check if the event is a keypress
            if (ev.type == KeyPress) {
                // Get the key code and modifiers
                KeyCode keyCode = ev.xkey.keycode;
                int modifiers = ev.xkey.state;
                // Log the keystroke
                printf("Key: %d (0x%x), modifiers: %d\n", keyCode, keyCode, modifiers);
            }
        }
    }

    // Clean up
    XUngrabKey(dpy, AnyKey, AnyModifier, win);
    XDestroyWindow(dpy, win);
    XCloseDisplay(dpy);
    return 0;
}
