Here is a simple C++ program that takes voltage (V) and current (I) as input and calculates power (P) and resistance (R) using the formulas:

Power (P) = V * I
Resistance (R) = V / I

```cpp
#include <iostream>
#include <limits>

using namespace std;

int main() {
    double voltage, current, power, resistance;

    // Input voltage and current
    cout << "Enter voltage (in volts): ";
    while (!(cin >> voltage)) {
        cout << "Invalid input. Please enter a valid voltage value." << endl;
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Enter current (in amperes): ";
    while (!(cin >> current)) {
        cout << "Invalid input. Please enter a valid current value." << endl;
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    // Calculate power and resistance
    power = voltage * current;
    resistance = voltage / current;

    // Output results
    cout << "Power (P) = " << power << " watts" << endl;
    cout << "Resistance (R) = " << resistance << " ohms" << endl;

    return 0;
}
```

