        resultRectangle += parameters[i].resultRectangle;
        resultTrapezoid += parameters[i].resultTrapezoid;
        resultSimpson += parameters[i].resultSimpson;
    }
    double averageRectangle = resultRectangle / n;
    double averageTrapezoid = resultTrapezoid / n;
