    double resultTrapezoid;
    double resultSimpson;
};

// Функция для вычисления интеграла в потоке
DWORD WINAPI integrate(LPVOID lpParameter) {
    Parameters* parameters = (Parameters*)lpParameter;

    // Вычисление интеграла методом прямоугольников
    double resultRectangle = integralRectangle(parameters->a, parameters->b, parameters->n);
