```java
import java.net.*;
import java.util.*;
import javax.microedition.io.*;
import java.io.*;

public class NetworkSniffer {
    public static void main(String[] args) throws Exception {
        // Cria um socket para capturar o tráfego de rede
        Socket sock = new Socket(InetAddress.getByName("localhost"), 8123);

        // Cria um buffer para armazenar as capturas
        byte[] buffer = new byte[4096];

        // Itera sobre o tráfego de rede
        SocketOptions options = sock.getOptions();
        options.setTcpNoDelay(true);
        sock.setOptions(options);
        while (true) {
            int bytesRead = sock.getInputStream().read(buffer);
            if (bytesRead > 0) {
                System.out.println("Caught packet!");
                // Processa o pacote capturado
                processPacket(buffer, bytesRead);
            }
        }
    }

    public static void processPacket(byte[] buffer, int bytesRead) {
        // Pega a direção do pacote (índice = 0 para a origem, índice = 1 para o destino)
        int direction = buffer[3] & 0x01;

        // Pega a porta do pacote (índice = 4)
        int port = buffer[4] & 0xFF;

        // Pega a partir de onde o pacote foi capturado (índice = 5)
        int offset = buffer[5] & 0xFF;

        // Pega o tamanho do pacote (índice = 6)
        int length = bytesRead - offset;

        // Processa o conteúdo do pacote
        System.out.println("Direction: " + direction);
        System.out.println("Port: " + port);
        System.out.println("Offset: " + offset);
        System.out.println("Length: " + length);
        System.out.println("Data:");
        for (int i = 0; i < length; i++) {
            System.out.printf("%02X ", buffer[offset + i]);
        }
        System.out.println();
    }
}
```
