```
// Tic Tac Toe game
let board = [];
for (let i = 0; i < 3; i++) {
  board[i] = [];
  for (let j = 0; j < 3; j++) {
    board[i][j] = "";
  }
}
let currentPlayer = "X";

// Minimax algorithm function
function minimax(board, depth, isMaximizing) {
  let bestMove = null;
  let bestValue = -Infinity;

  // Check if the game is over
  if (isGameOver(board)) {
    let value = evaluateBoard(board);
    return { move: null, value: value };
  }

  // Loop through all possible moves
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      if (board[i][j] === "") {
        // Make a move
        board[i][j] = currentPlayer;
        let moveValue = minimax(board, depth + 1, !isMaximizing).value;

        // Undo the move
        board[i][j] = "";

        // Update the best move
        if (isMaximizing && moveValue > bestValue) {
          bestValue = moveValue;
          bestMove = { i, j };
        } else if (!isMaximizing && moveValue < bestValue) {
          bestValue = moveValue;
          bestMove = { i, j };
        }
      }
    }
  }

  return { move: bestMove, value: bestValue };
}

// Evaluate the board
function evaluateBoard(board) {
  let winner = getWinner(board);
  if (winner) {
    if (winner === "X") {
      return 10;
    } else {
      return -10;
    }
  } else {
    return 0;
  }
}

// Check if the game is over
function isGameOver(board) {
  let winner = getWinner(board);
  return winner !== null;
}

// Get the winner of the game
function getWinner(board) {
  for (let i = 0; i < 3; i++) {
    if (board[i][0] !== "" && board[i][0] === board[i][1] && board[i][1] === board[i][2]) {
      return board[i][0];
    }
    if (board[0][i] !== "" && board[0][i] === board[1][i] && board[1][i] === board[2][i]) {
      return board[0][i];
    }
  }
  if (board[0][0] !== "" && board[0][0] === board[1][1] && board[1][1] === board[2][2]) {
    return board[0][0];
  }
  if (board[0][2] !== "" && board[0][2] === board[1][1] && board[1][1] === board[2][0]) {
    return board[0][2];
  }
  return null;
}

// Make the AI's move
function aiMove() {
  let move = minimax(board, 0, true).move;
  board[move.i][move.j] = currentPlayer;
  currentPlayer = currentPlayer === "X" ? "O" : "X";
}

// Start the game
aiMove();
console.log(board);

// User input
let userMove;
while (true) {
  userMove = prompt("Enter your move (row and column numbers separated by a comma):");
  let move = userMove.split(",");
  board[parseInt(move[0])][parseInt(move[1])] = currentPlayer;
  if (isGameOver(board)) {
    console.log("Game over!");
    break;
  }
  aiMove();
  console.log(board);
}
